  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for gui/public/views/orchestrator.js — WP-011
  5	 *
  6	 * All acceptance criteria tested:
  7	 *   AC-1: "Run Preflight" calls API.orchestratorStart(planPath, true) and
  8	 *         renders a pass/fail checklist.
  9	 *   AC-2: "Start Run" button disabled initially; enabled only when all
 10	 *         preflight checks pass; calls API.orchestratorStart(planPath, false).
 11	 *   AC-3: Queue table fetches on render and registers 5-second polling via
 12	 *         Router._setPolling. Each entry renders status badge, elapsed time,
 13	 *         and progress.
 14	 *   AC-4: Pending entries show kill button; started entries show project link;
 15	 *         dead entries show dismiss button.
 16	 *   AC-5: Expanding a row starts a log preview via
 17	 *         OrchestratorWidgets.renderLogPreview(); re-render calls its cleanup.
 18	 *   AC-6: CLI reference card HTML is present at the bottom of the view.
 19	 *   AC-7: All log preview cleanup functions are invoked when renderOrchestrator
 20	 *         is called a second time (re-render scenario).
 21	 *
 22	 * Uses jsdom + vm.runInThisContext to load the browser-side script.
 23	 * API, Router, OrchestratorWidgets, and escapeHtml are set on globalThis.
 24	 */
 25	
 26	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
 27	import { readFileSync } from 'node:fs';
 28	import { join } from 'node:path';
 29	import vm from 'node:vm';
 30	
 31	// ---------------------------------------------------------------------------
 32	// Load scripts
 33	// ---------------------------------------------------------------------------
 34	
 35	const publicDir = join(__dirname, '../../gui/public');
 36	
 37	const utilsJs        = readFileSync(join(publicDir, 'utils.js'), 'utf-8');
 38	const orchestratorJs = readFileSync(join(publicDir, 'views/orchestrator.js'), 'utf-8');
 39	
 40	// ---------------------------------------------------------------------------
 41	// Global type stubs
 42	// ---------------------------------------------------------------------------
 43	
 44	declare global {
 45	  // eslint-disable-next-line no-var
 46	  var renderOrchestrator: (app: HTMLElement) => void;
 47	  // eslint-disable-next-line no-var
 48	  var API: {
 49	    orchestratorStart:    Mock;
 50	    orchestratorGetQueue: Mock;
 51	    orchestratorKill:     Mock;
 52	    orchestratorDismiss:  Mock;
 53	  };
 54	  // eslint-disable-next-line no-var
 55	  var Router: {
 56	    _setPolling: Mock;
 57	    _clearPolling: Mock;
 58	  };
 59	  // eslint-disable-next-line no-var
 60	  var OrchestratorWidgets: {
 61	    renderCliReference:  Mock;
 62	    renderKillButton:    Mock;
 63	    renderDismissButton: Mock;
 64	    renderLogPreview:    Mock;
 65	    renderProgressBadge: Mock;
 66	    renderStatusCard:    Mock;
 67	  };
 68	}
 69	
 70	// ---------------------------------------------------------------------------
 71	// Setup: install globals, load scripts once
 72	// ---------------------------------------------------------------------------
 73	
 74	beforeAll(() => {
 75	  // Install utils.js globals (escapeHtml, etc.)
 76	  vm.runInThisContext(utilsJs);
 77	
 78	  // Stub API — individual tests override as needed via mockResolvedValue.
 79	  (globalThis as Record<string, unknown>)['API'] = {
 80	    orchestratorStart:    vi.fn().mockResolvedValue({ checks: [], started: false }),
 81	    orchestratorGetQueue: vi.fn().mockResolvedValue([]),
 82	    orchestratorKill:     vi.fn().mockResolvedValue(null),
 83	    orchestratorDismiss:  vi.fn().mockResolvedValue(null),
 84	  };
 85	
 86	  // Stub Router.
 87	  (globalThis as Record<string, unknown>)['Router'] = {
 88	    _setPolling:   vi.fn(),
 89	    _clearPolling: vi.fn(),
 90	  };
 91	
 92	  // Stub OrchestratorWidgets.
 93	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
 94	    renderCliReference:  vi.fn().mockReturnValue('<div class="cli-reference">CLI Ref</div>'),
 95	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
 96	      const btn = document.createElement('button');
 97	      btn.className = 'kill-btn';
 98	      btn.textContent = 'Kill';
 99	      return btn;
100	    }),

101	    renderDismissButton: vi.fn().mockImplementation((_id: string, _cb: () => void) => {
102	      const btn = document.createElement('button');
103	      btn.className = 'dismiss-btn';
104	      btn.textContent = 'Dismiss';
105	      return btn;
106	    }),
107	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()), // returns cleanup stub
108	    renderProgressBadge: vi.fn().mockReturnValue('<span class="badge-neutral">• idle</span>'),
109	    renderStatusCard:    vi.fn().mockReturnValue('<div>card</div>'),
110	  };
111	
112	  // Load the orchestrator view script.
113	  vm.runInThisContext(orchestratorJs);
114	});
115	
116	// Reset mocks before each test; restore real timers.
117	beforeEach(() => {
118	  vi.clearAllMocks();
119	
120	  // Reset to safe defaults.
121	  globalThis.API.orchestratorStart    = vi.fn().mockResolvedValue({ checks: [], started: false });
122	  globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
123	  globalThis.OrchestratorWidgets.renderCliReference = vi.fn()
124	    .mockReturnValue('<div class="cli-reference">CLI Ref</div>');
125	  globalThis.OrchestratorWidgets.renderProgressBadge = vi.fn()
126	    .mockReturnValue('<span class="badge-neutral">• idle</span>');
127	  globalThis.OrchestratorWidgets.renderKillButton = vi.fn()
128	    .mockImplementation((_id: string, _cb: () => void) => {
129	      const btn = document.createElement('button');
130	      btn.className = 'kill-btn';
131	      btn.textContent = 'Kill';
132	      return btn;
133	    });
134	  globalThis.OrchestratorWidgets.renderDismissButton = vi.fn()
135	    .mockImplementation((_id: string, _cb: () => void) => {
136	      const btn = document.createElement('button');
137	      btn.className = 'dismiss-btn';
138	      btn.textContent = 'Dismiss';
139	      return btn;
140	    });
141	  globalThis.OrchestratorWidgets.renderLogPreview = vi.fn()
142	    .mockReturnValue(vi.fn());
143	});
144	
145	afterEach(() => {
146	  vi.restoreAllMocks();
147	});
148	
149	// ---------------------------------------------------------------------------
150	// Helpers
151	// ---------------------------------------------------------------------------
152	
153	/** Flush pending microtask queues (multi-hop Promise chains). */
154	async function flushPromises(): Promise<void> {
155	  for (let i = 0; i < 10; i++) await Promise.resolve();
156	}
157	
158	/** Create a fresh #app element. */
159	function makeApp(): HTMLElement {
160	  const app = document.createElement('div');
161	  app.id = 'app';
162	  document.body.appendChild(app);
163	  return app;
164	}
165	
166	function cleanupApp(app: HTMLElement): void {
167	  app.remove();
168	}
169	
170	/** Build a minimal queue entry object. */
171	function makeEntry(overrides: Record<string, unknown> = {}): Record<string, unknown> {
172	  return {
173	    id:              'entry-abc',
174	    pid:             12345,
175	    planPath:        '/home/user/project/plan.md',
176	    expectedSlug:    'my-project',
177	    startedAt:       new Date(Date.now() - 70_000).toISOString(),
178	    effectiveStatus: 'pending',
179	    projectExists:   true,
180	    progress:        null,
181	    lastAction:      null,
182	    logFilename:     null,
183	    ...overrides,
184	  };
185	}
186	
187	// ---------------------------------------------------------------------------
188	// AC-6: CLI reference card
189	// ---------------------------------------------------------------------------
190	
191	describe('renderOrchestrator — AC-6: CLI reference', () => {
192	  it('renders the CLI reference card returned by OrchestratorWidgets', async () => {
193	    const app = makeApp();
194	    try {
195	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
196	      globalThis.OrchestratorWidgets.renderCliReference = vi.fn()
197	        .mockReturnValue('<div class="cli-reference">CLI COMMANDS</div>');
198	      renderOrchestrator(app);
199	      await flushPromises();
200	      expect(app.innerHTML).toContain('CLI COMMANDS');
201	    } finally { cleanupApp(app); }
202	  });
203	
204	  it('calls OrchestratorWidgets.renderCliReference()', () => {
205	    const app = makeApp();
206	    try {
207	      renderOrchestrator(app);
208	      expect(globalThis.OrchestratorWidgets.renderCliReference).toHaveBeenCalled();
209	    } finally { cleanupApp(app); }
210	  });
211	});
212	
213	// ---------------------------------------------------------------------------
214	// AC-3: Queue table + polling
215	// ---------------------------------------------------------------------------
216	
217	describe('renderOrchestrator — AC-3: queue + polling', () => {
218	  it('calls API.orchestratorGetQueue on render', async () => {
219	    const app = makeApp();
220	    try {
221	      renderOrchestrator(app);
222	      await flushPromises();
223	      expect(globalThis.API.orchestratorGetQueue).toHaveBeenCalledOnce();
224	    } finally { cleanupApp(app); }
225	  });
226	
227	  it('registers polling via Router._setPolling with 5000 ms', () => {
228	    const app = makeApp();
229	    try {
230	      renderOrchestrator(app);
231	      expect(globalThis.Router._setPolling).toHaveBeenCalledOnce();
232	      const [, delay] = (globalThis.Router._setPolling as Mock).mock.calls[0];
233	      expect(delay).toBe(5000);
234	    } finally { cleanupApp(app); }
235	  });
236	
237	  it('renders empty state message when queue is empty', async () => {
238	    const app = makeApp();
239	    try {
240	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([]);
241	      renderOrchestrator(app);
242	      await flushPromises();
243	      expect(app.innerHTML).toContain('No active runs');
244	    } finally { cleanupApp(app); }
245	  });
246	
247	  it('renders a table row for each queue entry', async () => {
248	    const app = makeApp();
249	    try {
250	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
251	        makeEntry({ id: 'e1' }),
252	        makeEntry({ id: 'e2' }),
253	      ]);
254	      renderOrchestrator(app);
255	      await flushPromises();
256	      const rows = app.querySelectorAll('.orch-queue-row');
257	      expect(rows.length).toBe(2);
258	    } finally { cleanupApp(app); }
259	  });
260	
261	  it('shows plan basename (not full path) in plan cell', async () => {
262	    const app = makeApp();
263	    try {
264	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
265	        makeEntry({ planPath: '/long/path/to/plan.md' }),
266	      ]);
267	      renderOrchestrator(app);
268	      await flushPromises();
269	      const planCell = app.querySelector('.orch-plan-cell');
270	      expect(planCell?.textContent?.trim()).toBe('plan.md');
271	    } finally { cleanupApp(app); }
272	  });
273	
274	  it('shows full path as a tooltip on the plan cell', async () => {
275	    const app = makeApp();
276	    try {
277	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
278	        makeEntry({ planPath: '/long/path/to/plan.md' }),
279	      ]);
280	      renderOrchestrator(app);
281	      await flushPromises();
282	      const planCell = app.querySelector('.orch-plan-cell');
283	      expect(planCell?.getAttribute('title')).toBe('/long/path/to/plan.md');
284	    } finally { cleanupApp(app); }
285	  });
286	
287	  it('renders a status badge for each entry', async () => {
288	    const app = makeApp();
289	    try {
290	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
291	        makeEntry({ effectiveStatus: 'pending' }),
292	      ]);
293	      renderOrchestrator(app);
294	      await flushPromises();
295	      const badge = app.querySelector('.badge-pending');
296	      expect(badge).not.toBeNull();
297	    } finally { cleanupApp(app); }
298	  });
299	
300	  it('calls OrchestratorWidgets.renderProgressBadge for each entry', async () => {

301	    const app = makeApp();
302	    try {
303	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
304	        makeEntry(),
305	        makeEntry({ id: 'entry-xyz' }),
306	      ]);
307	      renderOrchestrator(app);
308	      await flushPromises();
309	      expect(globalThis.OrchestratorWidgets.renderProgressBadge).toHaveBeenCalledTimes(2);
310	    } finally { cleanupApp(app); }
311	  });
312	});
313	
314	// ---------------------------------------------------------------------------
315	// AC-4: Per-status row actions
316	// ---------------------------------------------------------------------------
317	
318	describe('renderOrchestrator — AC-4: row actions', () => {
319	  it('shows kill button for pending entries', async () => {
320	    const app = makeApp();
321	    try {
322	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
323	        makeEntry({ effectiveStatus: 'pending' }),
324	      ]);
325	      renderOrchestrator(app);
326	      await flushPromises();
327	      expect(app.querySelector('.kill-btn')).not.toBeNull();
328	      expect(globalThis.OrchestratorWidgets.renderKillButton).toHaveBeenCalledOnce();
329	    } finally { cleanupApp(app); }
330	  });
331	
332	  it('shows project link for started entries', async () => {
333	    const app = makeApp();
334	    try {
335	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
336	        makeEntry({ effectiveStatus: 'started', expectedSlug: 'my-project' }),
337	      ]);
338	      renderOrchestrator(app);
339	      await flushPromises();
340	      const link = app.querySelector('.orch-project-link') as HTMLAnchorElement | null;
341	      expect(link).not.toBeNull();
342	      expect(link?.href).toContain('/projects/');
343	      expect(link?.href).toContain('my-project');
344	    } finally { cleanupApp(app); }
345	  });
346	
347	  it('shows dismiss button for dead entries', async () => {
348	    const app = makeApp();
349	    try {
350	      globalThis.API.orchestratorGetQueue = vi.fn().mockResolvedValue([
351	        makeEntry({ effectiveStatus: 'dead' }),
352	      ]);
353	      renderOrchestrator(app);
354	      await flushPromises();
355	      expect(app.querySelector('.dismiss-btn')).not.toBeNull();
356	      expect(globalThis.OrchestratorWidgets.renderDismissButton).toHaveBeenCalledOnce();
357	    } finally { cleanupApp(app); }
358	  });
359	});
360	
361	// ---------------------------------------------------------------------------
362	// AC-1: Preflight
363	// ---------------------------------------------------------------------------
364	
365	describe('renderOrchestrator — AC-1: preflight', () => {
366	  it('renders "Run Preflight" button', () => {
367	    const app = makeApp();
368	    try {
369	      renderOrchestrator(app);
370	      const btn = document.getElementById('orch-preflight-btn');
371	      expect(btn).not.toBeNull();
372	    } finally { cleanupApp(app); }
373	  });
374	
375	  it('calls API.orchestratorStart(planPath, true) when "Run Preflight" clicked', async () => {
376	    const app = makeApp();
377	    try {
378	      globalThis.API.orchestratorStart = vi.fn().mockResolvedValue({ checks: [], started: false });
379	      renderOrchestrator(app);
380	      const input = document.getElementById('orch-plan-path') as HTMLInputElement;
381	      const btn   = document.getElementById('orch-preflight-btn') as HTMLButtonElement;
382	      input.value = '/my/plan.md';
383	      btn.click();
384	      await flushPromises();
385	      expect(globalThis.API.orchestratorStart).toHaveBeenCalledWith('/my/plan.md', true);
386	    } finally { cleanupApp(app); }
387	  });
388	
389	  it('renders pass items with preflight-pass class', async () => {
390	    const app = makeApp();
391	    try {
392	      globalThis.API.orchestratorStart = vi.fn().mockResolvedValue({
393	        checks: [{ name: 'Venv', pass: true, detail: 'OK' }],
394	        started: false,
395	      });
396	      renderOrchestrator(app);
397	      const input = document.getElementById('orch-plan-path') as HTMLInputElement;
398	      input.value = '/my/plan.md';
399	      (document.getElementById('orch-preflight-btn') as HTMLButtonElement).click();
400	      await flushPromises();
401	      expect(app.querySelector('.preflight-pass')).not.toBeNull();
402	    } finally { cleanupApp(app); }
403	  });
404	
405	  it('renders fail items with preflight-fail class', async () => {
406	    const app = makeApp();
407	    try {
408	      globalThis.API.orchestratorStart = vi.fn().mockResolvedValue({
409	        checks: [{ name: 'MCP dist', pass: false, detail: 'Stale', fix: 'npm run build' }],
410	        started: false,
411	      });
412	      renderOrchestrator(app);
413	      const input = document.getElementById('orch-plan-path') as HTMLInputElement;
414	      input.value = '/my/plan.md';
415	      (document.getElementById('orch-preflight-btn') as HTMLButtonElement).click();
416	      await flushPromises();
417	      expect(app.querySelector('.preflight-fail')).not.toBeNull();
418	    } finally { cleanupApp(app); }
419	  });
